class ADAA(metaclass=ABCMeta):
    """
    ADAA is an acronym for Aligned Data Access Array.
    This data type is intended for the systematic distribution of data into
    multiple aligned arrays. An example for this distribution are arrays
    holding the real and imaginary parts of numbers that were originally
    stored in a complex array. The distribution does not require more memory
    but might allow optimizations based on the active distinction between
    e.g. real and imaginary parts.

    The base class implements just this case and comes along with basic
    arithmetic operations.
    """

    _IDENTIFIER = "COMPLEX_ARRAY"

    def __init__(self, size: int):
        self._size = size
        self._data_r = None
        self._data_i = None
        self.reinit(size)

    @property
    def real(self):
        """Access protected attribute real."""
        return self._safe_access_real()

    @real.setter
    def real(self, arr):
        """Set the data for real part."""
        # self._set_data(real=arr)
        raise ValueError("Real part of the data cannot be set directly.")

    @property
    def imag(self):
        """Access protected attribute imag."""
        return self._safe_access_imag()

    @imag.setter
    def imag(self, arr):
        """Set the data for imag part."""
        # self._set_data(imag=arr)
        raise ValueError("Imag part of the data cannot be set directly.")

    @property
    def ident(self) -> str:
        """access write-protected property 'identifier'"""
        return self._IDENTIFIER

    @property
    def size(self) -> int:
        """Access write-protected property 'size'"""
        return self._size

    @classmethod
    def from_numpy(cls, arr: np.ndarray) -> ADAA:
        """Import data from numpy array."""
        return cls._from_numpy(arr)

    def to_numpy(self) -> np.ndarray:
        """Export data as numpy array."""
        return self._to_numpy()

    def unpack(self) -> tuple:
        """Unpack the layer into a tuple to apply it to functions."""
        return (self._data_r, self._data_i, self.size)

    def copy(self) -> ADAA:
        """Creates a real copy of self."""
        copy = self.__class__(self.size)
        self.__class__.coeff_linop(copy.real, 0.0, 1.0, self.real)
        self.__class__.coeff_linop(copy.imag, 0.0, 1.0, self.imag)
        return copy

    @classmethod
    def allclose(cls, op_a, op_b, rtol=1e-05, atol=1e-8):
        """
        Check if the values are all sufficiently close by checking, if
        |a - b|² <= atol² + rtol² (|a|² + |b|²) / 4
        is fulfilled for all coefficients.
        """
        ref_squared = cls.new_data_array(op_a.size, "f64")
        dif_squared = cls.new_data_array(op_a.size, "f64")
        dif = op_a - op_b
        cls.coeff_linop(
            dif_squared,
            0.0,
            1.0,
            cls.coeff_norm2(dif.real, dif.imag),
        )
        cls.coeff_linop(
            ref_squared,
            atol**2,
            rtol**2 / 4,
            cls.coeff_norm2(op_a.real, op_a.imag),
            rtol**2 / 4,
            cls.coeff_norm2(op_b.real, op_b.imag),
        )

        # check if ref_squared - dif_squared >= 0
        return cls.coeff_all_nonneg(
            cls.coeff_linop(0.0, -1.0, dif_squared, 1.0, ref_squared)
        )

    @classmethod
    def _new_data_arrays(cls, size: int) -> Tuple:
        """Create all arrays for a new array."""
        return (
            cls.new_data_array(size, "f64"),
            cls.new_data_array(size, "f64"),
        )

    def reinit(self, size=None):
        """Reinitialize the data for a certain size"""
        if size is None:
            size = self.size
        else:
            if size == self.size:
                return
        self._reinit(size)

    def _reinit(self, size):
        """Actual reinitialization. Forced."""
        self._data_r = self.new_data_array(size, "f64")
        self._data_i = self.new_data_array(size, "f64")
        assert self._size == size

    def __init_subclass__(cls, ident=None):
        """
        When a new subclass is derived, introduce the class
        variable _IDENTIFIER.
        """
        if ident is None:
            ident = cls.__name__
        cls._IDENTIFIER = ident

    def _set_data(self, real=None, imag=None):
        """Set the data."""
        if real is not None:
            self._data_r = real
        if imag is not None:
            self._data_i = imag
        return self

    ###########################################################################
    #
    # ABSTRACT methods
    # ================
    #
    # general routines
    # ----------------

    @abstractmethod
    def _safe_access_real(self) -> Any:
        """Provide safe access to real part."""
        # return self._data_r.copy()

    @abstractmethod
    def _safe_access_imag(self) -> Any:
        """Provide safe access to imag part."""
        # return self._data_i.copy()

    @classmethod
    @abstractmethod
    def _from_numpy(cls, array):
        """Internal call from_numpy."""
        # size = len(array)
        # return cls(size)._set_data(
        #     real=np.array(array).real, imag=np.array(array).imag
        # )

    @abstractmethod
    def _to_numpy(self):
        """Transfer data to numpy."""
        # return (
        #     0
        #     + (self._data_r if self._data_r else 0)
        #     + (1j * self._data_i.copy() if self._data_i else 0)
        # )

    @classmethod
    @abstractmethod
    def new_data_array(cls, size: int, dtype: str = "f64") -> Any:
        """Create one of the arrays for a new ADAA."""
        # match dtype:
        #     case "f64":
        #         return (np.zeros(size, dtype=np.float64),)
        #     case _:
        #         raise ValueError(f"Unsupported dtype: {dtype}")

    @abstractmethod
    def to_zero(self):
        """Set the coefficient data to zero."""
        # if self._data_r is not None:
        #     self._data_r *= 0
        # if self._data_i is not None:
        #     self._data_i *= 0
        # return self

    ###########################################################################
    #
    # ABSTRACT methods
    # ================
    #
    # applied @ coefficients
    # ----------------------

    @classmethod
    @abstractmethod
    def coeff_norm2(cls, arr_real, arr_imag=None):
        """return a coeff array with the normed square in each entry"""
        # return arr_real * arr_real (+ arr_imag * arr_imag if arr_imag)

    @classmethod
    @abstractmethod
    def coeff_all_nonneg(cls, array):
        """Checks if all entries in the coeffs are positive"""
        # return np.min(array) >= 0

    @classmethod
    @abstractmethod
    def coeff_linop(
        cls, arr_r, /, scal_a, scal_b, arr_c, scal_d=1, arr_e=None
    ):
        """
        Performs the basic linear operation
            a + b * c (+ d * e)
        where a and b are scalar and c is a coeff array.
        """
        # writes the result of scal_a + scal_b * arr_c (+ scal_d * arr_e if arr_e) into arr_r

    @classmethod
    @abstractmethod
    def basic_linop(cls, op_r, /, op_a=None, sc_b=None, op_c=None, size=None):
        """returns operator_a + scalar_b * operator_c"""

        assert op_c is not None

        if size is None:
            size = op_c.size

        op_r.reinit(size)

        if op_a is None:
            zero = cls(size).to_zero()
            oar, oai = zero.real, zero.imag
        else:
            oar = op_a.real
            oai = op_a.imag

        ocr = op_c.real
        oci = op_c.imag

        if sc_b is None:
            sbr, sbi = (1.0, 0.0)
        else:
            sbr, sbi = (complex(sc_b).real, complex(sc_b).real)

        aux_r, aux_i = cls._new_data_arrays(size)
        aux_r, aux_i = cls._new_data_arrays(size)

        # sbr * ocr - sbi * oci -> aux_r
        cls.coeff_linop(aux_r, 0.0, sbr, ocr, -1 * sbi, oci)
        # sbi * ocr + sbr * oci -> aux_i
        cls.coeff_linop(aux_i, 0.0, sbi, ocr, sbr, oci)

        # bracket + oar -> op_r.real
        cls.coeff_linop(op_r.real, 0.0, 1.0, aux_r, 1.0, oar)
        # bracket + oai -> op_r.imag
        cls.coeff_linop(op_r.imag, 0.0, 1.0, aux_i, 1.0, oai)

    def __add__(self, other):
        if isinstance(other, self.__class__):
            assert self.size == other.size
            assert self.ident == other.ident
            result = self.__class__(size=self.size)
            self.basic_linop(result, op_a=self, sc_b=1, op_c=other)
            return result
        raise ValueError(
            "Subtraction between operator and non-operator is not supported"
        )

    def __sub__(self, other):
        if isinstance(other, self.__class__):
            assert self.size == other.size
            assert self.ident == other.ident
            result = self.__class__(size=self.size)
            self.basic_linop(result, op_a=self, sc_b=-1, op_c=other)
            return result
        raise ValueError(
            "Subtraction between operator and non-operator is not supported"
        )

    def __mul__(self, other):
        if isinstance(other, ADAA):
            raise ValueError(
                "Multiplication with other operator is not supported"
            )
        result = self.__class__(size=self.size)
        self.basic_linop(result, op_a=None, sc_b=other, op_c=self)
        return result

    def __truediv__(self, other):
        if isinstance(other, ADAA):
            raise ValueError("Dividing through operator is not supported")
        result = self.__class__(size=self.size)
        inv_other = 1.0 / other
        self.basic_linop(result, op_a=None, sc_b=inv_other, op_c=self)
        return result

    def __rmul__(self, other):
        # assume commutative, because if the other operator is an ADAA as well,
        # why else should rmul be called?
        return self.__mul__(other)

    def __neg__(self):
        result = self.__class__(size=self.size)
        self.basic_linop(result, op_a=None, sc_b=-1, op_c=self)
        return result

    def __len__(self):
        return self.size

    def __bool__(self):
        return self.size > 0

    def __eq__(self, other):
        return self.__class__.allclose(
            self, other
        )  # , rtol=1e-08, atol=1e-12)


class DContainer:
    """DContainer class description"""

    _LAYERS: dict[str, ADAA] = {}

    def __init__(self, *sizes):
        if len(sizes) != len(self._LAYERS):
            raise ValueError("Sizes must match the number of layers")
        self._layers = {
            key: layer(size)
            for (key, layer), size in zip(self._LAYERS.items(), sizes)
        }

    def __init_subclass__(cls, **layers):
        cls._LAYERS = layers
        return cls

    def __getitem__(self, key):
        assert key in self._layers
        return self._layers[key]

    def unpack(self, key, **kwargs):
        """unpack the requested layer"""
        assert key in self._layers
        return self._layers[key].unpack(**kwargs)

    def unpack_multi(self, keys, **kwargs):
        """unpack the requested layer"""
        for key in keys:
            assert key in self._layers
        return [self._layers[key].unpack(**kwargs) for key in keys]


class DLC(DContainer):
    """Dual Layer Container class. Implements host-device interaction"""


class SDLC(DLC):
    """Synced Dual Layer Container class"""


